import React, { useState } from 'react';

function Contact({ content }) {
  const [status, setStatus] = useState({
    type: 'idle',
    message: '',
  });

  const handleSubmit = async (event) => {
    event.preventDefault();

    setStatus({
      type: 'loading',
      message: content.status.loading,
    });

    const form = event.currentTarget;
    const formData = new FormData(form);

    formData.append('_subject', content.subject);
    formData.append('_template', 'table');

    if (typeof window !== 'undefined') {
      formData.append('_url', window.location.href);
    }

    try {
      const response = await fetch(
        'https://formsubmit.co/ajax/rafaelcamachofitti15@gmail.com',
        {
          method: 'POST',
          headers: {
            Accept: 'application/json',
          },
          body: formData,
        }
      );

      const result = await response.json();

      if (!response.ok || result.success === false) {
        throw new Error(result.message || 'Falha no envio.');
      }

      setStatus({
        type: 'success',
        message: content.status.success,
      });
      form.reset();
    } catch (error) {
      setStatus({
        type: 'error',
        message: content.status.error,
      });
    }
  };

  return (
    <section id="contact" className="section">
      <div className="container">
        <div className="section__heading">
          <span className="eyebrow">{content.eyebrow}</span>
          <h2>{content.title}</h2>
          <p>{content.description}</p>
        </div>
        <div className="contact__grid">
          <div className="glass card contact__panel">
            <div className="contact__info">
              <p>
                <strong>{content.infoLabels.email}</strong>
                <a href="mailto:rafaelcamachofitti15@gmail.com">
                  rafaelcamachofitti15@gmail.com
                </a>
              </p>
              <p>
                <strong>{content.infoLabels.phone}</strong>
                <a href="tel:+5531984440770">(31) 98444-0770</a>
              </p>
              <p>
                <strong>{content.infoLabels.base}</strong>
                <span>{content.location}</span>
              </p>
            </div>
          </div>
          <div className="glass card contact">
            <form onSubmit={handleSubmit} className="contact__form">
              <div className="form__group">
                <label htmlFor="name">{content.fields.nameLabel}</label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  placeholder={content.fields.namePlaceholder}
                  required
                />
              </div>
              <div className="form__group">
                <label htmlFor="email">{content.fields.emailLabel}</label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  placeholder={content.fields.emailPlaceholder}
                  required
                />
              </div>
              <div className="form__group">
                <label htmlFor="message">{content.fields.messageLabel}</label>
                <textarea
                  id="message"
                  name="message"
                  rows="5"
                  placeholder={content.fields.messagePlaceholder}
                  required
                ></textarea>
              </div>
              <input
                type="text"
                name="_honey"
                className="contact__honeypot"
                tabIndex="-1"
                autoComplete="off"
              />
              <button
                type="submit"
                className="btn"
                disabled={status.type === 'loading'}
              >
                {status.type === 'loading' ? content.submitting : content.submit}
              </button>
              {status.type !== 'idle' && (
                <p className={`contact__status contact__status--${status.type}`}>
                  {status.message}
                </p>
              )}
            </form>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Contact;
